function normalize(text) {
  return String(text || "").replace(/^ال/, "").trim();
}

function makeEntry([letter, id, title, category, scripture, place, people, study]) {
  return {
    id,
    title,
    letter,
    category,
    content: `الشواهد الأساسية: ${scripture}.\n\nالمكان والسياق: ${place}.\n\nالأشخاص المرتبطون بالنص: ${people}.\n\nالدراسة اللاهوتية: ${study}`,
    references: [
      { author: "الكتاب المقدس", title: scripture },
      DEFAULT_SOURCE
    ],
    status: "reviewed"
  };
}

const data = JSON.parse(fs.readFileSync(file, "utf8"));
if (!Array.isArray(data.entries)) {
  throw new Error("encyclopedia_ar.json لا يحتوي على entries.");
}

const existingIds = new Set(data.entries.map(entry => entry.id));
const existingTitles = new Set(data.entries.map(entry => `${entry.letter}:${normalize(entry.title)}`));
const counts = new Map();
for (const entry of data.entries) {
  counts.set(entry.letter, (counts.get(entry.letter) || 0) + 1);
}

const addedByLetter = new Map();
const added = [];
for (const row of candidates) {
  const [letter, id, title] = row;
  if ((counts.get(letter) || 0) >= TARGET) continue;
  const titleKey = `${letter}:${normalize(title)}`;
  if (existingIds.has(id) || existingTitles.has(titleKey)) continue;
  const entry = makeEntry(row);
  for (const field of ["id", "title", "letter", "category", "content", "references", "status"]) {
    if (!entry[field]) throw new Error(`حقل ناقص في ${id}: ${field}`);
  }
  data.entries.push(entry);
  existingIds.add(id);
  existingTitles.add(titleKey);
  counts.set(letter, (counts.get(letter) || 0) + 1);
  addedByLetter.set(letter, (addedByLetter.get(letter) || 0) + 1);
  added.push(entry);
}

const missing = [...new Set(candidates.map(row => row[0]))]
  .sort((a, b) => a.localeCompare(b, "ar"))
  .filter(letter => (counts.get(letter) || 0) < TARGET);

if (missing.length) {
  throw new Error(`لم تكتمل الحروف: ${missing.map(letter => `${letter}=${counts.get(letter) || 0}`).join(", ")}`);
}

const temp = `${file}.${process.pid}.tmp`;
fs.writeFileSync(temp, `${JSON.stringify(data, null, 2)}\n`, "utf8");
JSON.parse(fs.readFileSync(temp, "utf8"));
fs.renameSync(temp, file);

const summary = [...addedByLetter.entries()]
  .sort((a, b) => a[0].localeCompare(b[0], "ar"))
  .map(([letter, count]) => `${letter}: +${count} => ${counts.get(letter)}`)
  .join(" | ");

console.log(`تمت إضافة ${added.length} مدخلًا لإكمال الحروف الناقصة إلى ${TARGET} مدخلًا على الأقل.`);
console.log(summary);